mapper.select:

SELECT 'agent' AS metric_code,
0 AS total_count,
COUNT(*) AS today_increase
FROM bt_bot_scene
WHERE tenant_id = #{tenantId}
AND status_cd = '00A'

AND scene_type != 'a2a'
AND created_time >= #{todayStart}
AND created_time < #{tomorrowStart}

UNION ALL


SELECT 'knowledge' AS metric_code,
0 AS total_count,
COUNT(*) AS today_increase

FROM bt_knowledge_base
WHERE tenant_id = #{tenantId}
AND status_cd = '00A'
AND created_time >= #{todayStart}
AND created_time < #{tomorrowStart}


SELECT COUNT(*)

FROM bt_model_usage_log

WHERE tenant_id = #{tenantId}
  AND start_time >= #{startTime}
  AND start_time < #{endTime}


SELECT COUNT(*)

FROM bt_document d

WHERE d.tenant_id = #{tenantId}
  AND d.status_cd = '00A'

  AND d.doc_status = #{successStatus}

  AND d.parse_started_time >= #{startTime}
  AND d.parse_started_time < #{endTime}

  AND EXISTS (
    SELECT 1
    FROM bt_knowledge_base kb
    WHERE kb.knowledge_id = d.knowledge_id
      AND kb.tenant_id = d.tenant_id
      AND kb.status_cd = '00A'
  )
